class CommandParser(ArgumentParser):
    """
    Customized ArgumentParser class to improve some error messages and prevent
    SystemExit in several occasions, as SystemExit is unacceptable when a
    command is called programmatically.
    """

    def __init__(
        self, *, missing_args_message=None, called_from_command_line=None, **kwargs
    ):
        self.missing_args_message = missing_args_message
        self.called_from_command_line = called_from_command_line
        super().__init__(**kwargs)

    class CommandSubParsersAction(argparse._SubParsersAction):
        """Subparsers action that propagates Django-specific parser kwargs.

        ``CommandParser`` takes additional keyword arguments (e.g.
        ``called_from_command_line``) used to format errors appropriately when
        invoked via ``manage.py``/``django-admin``.

        Python's ``argparse`` doesn't copy these extra kwargs when constructing
        subparsers via ``add_subparsers().add_parser()`` which can lead to
        subparser parsing errors being raised as ``CommandError`` (and thus
        displayed as a traceback) instead of the normal CLI usage message.
        """

        def __init__(
            self,
            *args,
            missing_args_message=None,
            called_from_command_line=None,
            **kwargs,
        ):
            self._missing_args_message = missing_args_message
            self._called_from_command_line = called_from_command_line
            super().__init__(*args, **kwargs)

        def add_parser(self, name, **kwargs):
            # Only pass Django-specific kwargs to parsers that are (a subclass
            # of) CommandParser.
            try:
                is_command_parser = issubclass(self._parser_class, CommandParser)
            except TypeError:
                is_command_parser = False
            if is_command_parser:
                kwargs.setdefault("missing_args_message", self._missing_args_message)
                kwargs.setdefault("called_from_command_line", self._called_from_command_line)
            return super().add_parser(name, **kwargs)

    def add_subparsers(self, **kwargs):
        kwargs.setdefault("missing_args_message", self.missing_args_message)
        kwargs.setdefault("called_from_command_line", self.called_from_command_line)
        kwargs.setdefault("action", self.CommandSubParsersAction)
        return super().add_subparsers(**kwargs)

    def parse_args(self, args=None, namespace=None):
        # Catch missing argument for a better error message
        if self.missing_args_message and not (
            args or any(not arg.startswith("-") for arg in args)
        ):
            self.error(self.missing_args_message)
        return super().parse_args(args, namespace)

    def error(self, message):
        if self.called_from_command_line:
            super().error(message)
        else:
            raise CommandError("Error: %s" % message)


def handle_default_options(options):
    """
    Include any default options that all commands should accept here
    so that ManagementUtility can handle them before searching for
    user commands.
    """
    if options.settings:
        os.environ["DJANGO_SETTINGS_MODULE"] = options.settings
    if options.pythonpath:
        sys.path.insert(0, options.pythonpath)


